package ru.kupiora.radar;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;
final class BasketScreen {
 static JSONObject data(MainActivity a)throws Exception{try(java.io.InputStream in=a.getAssets().open("basket-data.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONObject(out.toString("UTF-8"));}}
 static String money(double n){return String.format(new Locale("ru","RU"),"%,.2f ₽",n);}
 static void entry(MainActivity a,LinearLayout parent){LinearLayout c=a.card();TextView title=a.text("Потребительская корзина  ›",18,a.CYAN);title.setMinHeight(a.dp(48));title.setFocusable(true);title.setOnClickListener(v->a.show("basket"));c.addView(title);try{JSONObject d=data(a);String region=Store.prefs(a).getString("basket_region","Россия");JSONObject match=find(d,region);c.addView(a.text(match==null?region+" · данных пока нет":money(match.getDouble("amount"))+" / месяц · "+region,15,a.TEXT));c.addView(a.text(d.getString("periodLabel")+" · архивный срез, не сегодняшняя цена",12,a.MUTED));}catch(Exception e){c.addView(a.text("Данные временно недоступны",14,a.MUTED));}parent.addView(c);}
 static JSONObject find(JSONObject d,String name){JSONArray regions=d.optJSONArray("regions");if(regions==null)return null;for(int i=0;i<regions.length();i++){JSONObject r=regions.optJSONObject(i);if(r!=null&&r.optString("name").equalsIgnoreCase(name.trim()))return r;}return null;}
 static void show(MainActivity a){a.body.addView(a.button("← Покупки и права",()->a.show("topic:consumer")));a.body.addView(a.text("Потребительская корзина",27,a.TEXT));a.body.addView(a.text("Статистический ориентир расходов на продукты питания. Это отдельный показатель цен, а не изменение законодательства.",15,a.MUTED));
 try{JSONObject d=data(a);String region=Store.prefs(a).getString("basket_region","Россия");JSONObject r=find(d,region);LinearLayout card=a.card();card.addView(a.text(region,18,a.CYAN));card.addView(a.text(r==null?"Нет проверенных данных":money(r.getDouble("amount")),30,a.TEXT));card.addView(a.text("На одного человека в месяц · "+d.getString("periodLabel"),14,a.MUTED));card.addView(a.text("АРХИВ · актуальная цена за текущий месяц ещё не загружена. Автоматическое обновление корзины пока не подключено.",13,a.MUTED));a.body.addView(card);
 a.body.addView(a.button("Выбрать регион вручную",()->choose(a)));a.body.addView(a.button("Определить мой регион",()->new android.app.AlertDialog.Builder(a).setTitle("Определить регион?").setMessage("Приложение запросит приблизительное местоположение один раз. Системный сервис Android определит название региона по координатам. Сохраним только выбранное название на телефоне. Можно отказаться и выбрать вручную.").setNegativeButton("Не сейчас",null).setPositiveButton("Продолжить",(dialog,which)->{if(a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION},21);else locate(a);}).show()));
 a.body.addView(a.text("Регион хранится только на этом устройстве. Геолокация не работает в фоне.",12,a.MUTED));
 if(r!=null){JSONArray ids=r.getJSONArray("sourceIndices");String check=ids.length()>1?"Сумма совпадает в трёх публикациях Росстата. Это одна статистическая система, а не три независимых измерения. Разные регионы и месяцы не усредняются.":"Подтверждено одной региональной публикацией Росстата. Сумма другого региона не подставляется.";a.body.addView(a.text(check,14,a.MUTED));for(int i=0;i<ids.length();i++){JSONObject source=d.getJSONArray("sources").getJSONObject(ids.getInt(i));a.body.addView(a.sourceFooter("Официальный источник · "+source.getString("title")+" ↗",source.getString("url")));}}else a.body.addView(a.text("Для выбранного региона в проверенной подборке ещё нет суммы. Вы можете явно выбрать «Россия», чтобы посмотреть общероссийский ориентир.",15,a.MUTED));
 a.body.addView(a.text("Что входит в набор",22,a.TEXT));a.body.addView(a.text("33 продукта. Количества ниже — условные статистические веса за год; они не являются персональной нормой питания. Помесячные цены отдельных продуктов в этой версии не загружены, поэтому разбивку суммы по товарам не показываем.",14,a.MUTED));
 Button expand=a.button("Показать состав · 33 продукта",()->{});a.body.addView(expand);LinearLayout items=new LinearLayout(a);items.setOrientation(LinearLayout.VERTICAL);items.setVisibility(android.view.View.GONE);JSONArray rows=d.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject item=rows.getJSONObject(i);items.addView(a.text(item.getString("name")+" · "+String.format(new Locale("ru","RU"),"%.2f",item.getDouble("annualQuantity"))+" "+item.getString("unit")+" / год",15,a.TEXT));}a.body.addView(items);expand.setOnClickListener(v->{boolean open=items.getVisibility()!=android.view.View.VISIBLE;items.setVisibility(open?android.view.View.VISIBLE:android.view.View.GONE);expand.setText(open?"Скрыть состав":"Показать состав · 33 продукта");});a.body.addView(a.sourceFooter("Официальный источник · состав и методология ↗",d.getString("compositionSource")));
 }catch(Exception e){a.body.addView(a.text("Не удалось прочитать данные корзины. Попробуйте открыть раздел снова.",16,a.MUTED));}}
 static void choose(MainActivity a){AutoCompleteTextView input=new AutoCompleteTextView(a);input.setSingleLine(true);input.setText(Store.prefs(a).getString("basket_region","Россия"));input.setSelectAllOnFocus(true);input.setHint("Область, край или республика");input.setThreshold(1);input.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_dropdown_item_1line,new String[]{"Россия","Москва","Московская область","Санкт-Петербург","Ленинградская область","Ставропольский край","Кабардино-Балкарская Республика","Республика Татарстан","Новосибирская область","Краснодарский край","Свердловская область"}));new android.app.AlertDialog.Builder(a).setTitle("Регион корзины").setMessage("Выберите подсказку или введите свой регион. Проверенные суммы сейчас есть для России, Ставропольского края и Кабардино-Балкарии.").setView(input).setNegativeButton("Отмена",null).setPositiveButton("Выбрать",(dialog,which)->{String name=input.getText().toString().trim();if(name.isEmpty()){Toast.makeText(a,"Введите название региона",Toast.LENGTH_SHORT).show();return;}Store.prefs(a).edit().putString("basket_region",name).apply();a.show("basket");}).show();}
 static void locate(MainActivity a){if(a.regionLocator!=null)a.regionLocator.close();a.regionLocator=new RegionLocator(a);a.regionLocator.start();}
}
